var a = [_]i32{ 27, 64, 13, 88, 41, 5, 72, 36 };
var total: usize = 0;
for (1..8) |pass| {
    var swapped = false;
    for (0..8 - pass) |j| {
        if (a[j] > a[j + 1]) {
            std.mem.swap(i32, &a[j], &a[j + 1]);
            total += 1;
            swapped = true;
    try out.print("pass {d}:", .{pass});
    for (a) |v|
        try out.print(" {d}", .{v});
    try out.writeByte('\n');
    if (!swapped)
        break;
try out.print("swaps: {d}\n", .{total});
